package com.fireplatform;

import com.fireplatform.simbinding.SimBindingConflicts;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.assertj.core.api.Assertions.*;

class SimBindingMigrationTest {
    record Db(String url,JdbcTemplate jdbc){ }
    final SimCardMigrationTest fixtures=new SimCardMigrationTest();
    Db db(String target,String ordering){String url="jdbc:h2:mem:sim-binding-migration-"+UUID.randomUUID()+";MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DEFAULT_NULL_ORDERING="+ordering+";DB_CLOSE_DELAY=-1";var config=Flyway.configure().dataSource(url,"sa","");config.target(target==null?"15":target);config.load().migrate();return new Db(url,new JdbcTemplate(new DriverManagerDataSource(url,"sa","")));}
    void latest(Db db){Flyway.configure().dataSource(db.url(),"sa","").target("15").load().migrate();}
    void devices(JdbcTemplate j){for(String tenant:List.of("a","b"))for(int i=0;i<2;i++)j.update("INSERT INTO devices(id,tenant_id,name,device_eui,model,address,physical_state) VALUES (?,?,?,?,'m','','NORMAL')",tenant+"-legacy-device-"+i,tenant,"Synthetic",UUID.randomUUID().toString());}
    void current(JdbcTemplate j,String card,String tenant,String device,long revision){j.update("INSERT INTO sim_card_associations(card_id,tenant_id,device_id,revision,recorded_at) VALUES (?,?,?,?,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00')",card,tenant,device,revision);}
    void change(JdbcTemplate j,String card,String tenant,long revision,String operation,String from,String to){j.update("INSERT INTO sim_card_association_changes(id,card_id,tenant_id,revision,operation,from_device_id,to_device_id,reason,recorded_at,actor_user_id) VALUES (?,?,?,?,?,?,?,'',TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00','actor')",UUID.randomUUID().toString(),card,tenant,revision,operation,from,to);}
    @Test void latestAddsExactlyTwoEmptyTablesWithFiveAndTenPhysicalColumns(){var j=db(null,"LOW").jdbc();assertThat(fixtures.tables(j)).hasSize(50).contains("sim_card_associations","sim_card_association_changes");for(String table:List.of("sim_card_associations","sim_card_association_changes","user_permissions"))assertThat(j.queryForObject("SELECT COUNT(*) FROM "+table,Long.class)).isZero();assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_card_associations' ORDER BY ordinal_position",String.class)).containsExactly("card_id","tenant_id","device_id","revision","recorded_at");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_card_association_changes' ORDER BY ordinal_position",String.class)).containsExactly("id","card_id","tenant_id","revision","operation","from_device_id","to_device_id","reason","recorded_at","actor_user_id");}
    @Test void v14UpgradePreservesAll48OldFactsSchemaConstraintsAndIndexesExceptOneExactRootRight(){var db=db("14","LOW");var j=db.jdbc();fixtures.tenant(j);devices(j);fixtures.user(j,"bootstrap-admin","PLATFORM",true);fixtures.user(j,"other-protected","PLATFORM",true);j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','sim-cards:read'),('bootstrap-admin','sim-cards:write'),('other-protected','device:read')");fixtures.card(j,"a","000Legacy");var old=fixtures.tables(j);assertThat(old).hasSize(48);var before=fixtures.facts(j,old);var columns=j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' ORDER BY table_name,ordinal_position");var constraints=j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public' ORDER BY table_name,constraint_name");var indexes=j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public' ORDER BY table_name,index_name");latest(db);assertThat(fixtures.tables(j)).hasSize(50).containsAll(old);var after=fixtures.facts(j,old);after.put("user_permissions",j.queryForList("SELECT * FROM user_permissions WHERE permission<>'sim-cards:bind'"));assertThat(after).isEqualTo(before);assertThat(j.queryForList("SELECT user_id FROM user_permissions WHERE permission='sim-cards:bind'",String.class)).containsExactly("bootstrap-admin");String oldOnly=" AND table_name NOT IN ('sim_card_associations','sim_card_association_changes')";assertThat(j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,ordinal_position")).isEqualTo(columns);assertThat(j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,constraint_name")).isEqualTo(constraints);assertThat(j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public'"+oldOnly+" ORDER BY table_name,index_name")).isEqualTo(indexes);}
    @Test void grantRequiresExactBootstrapIdPlatformAndProtectedWithoutImplicitReadWrite(){for(String type:List.of("PLATFORM","CUSTOMER"))for(boolean protectedUser:List.of(false,true)){var db=db("14","LOW");var j=db.jdbc();fixtures.tenant(j);fixtures.user(j,"bootstrap-admin",type,protectedUser);fixtures.user(j,"other-protected","PLATFORM",true);latest(db);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions",Long.class)).isEqualTo(type.equals("PLATFORM")&&protectedUser?1L:0L);if(type.equals("PLATFORM")&&protectedUser)assertThat(j.queryForList("SELECT permission FROM user_permissions",String.class)).containsExactly("sim-cards:bind");}}
    @Test void absentRootGetsNoSeedAndExistingBindRightAndRepeatedLatestAreIdempotent(){var absent=db("14","LOW");latest(absent);assertThat(absent.jdbc().queryForObject("SELECT COUNT(*) FROM app_users",Long.class)).isZero();var db=db("14","HIGH");var j=db.jdbc();fixtures.tenant(j);fixtures.user(j,"bootstrap-admin","PLATFORM",true);j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','sim-cards:bind')");latest(db);String card=fixtures.card(j,"a","Existing");devices(j);fixtures.user(j,"actor","PLATFORM",false);current(j,card,"a","a-legacy-device-0",1);change(j,card,"a",1,"BIND",null,"a-legacy-device-0");var before=fixtures.facts(j,fixtures.tables(j));latest(db);latest(db);assertThat(fixtures.facts(j,fixtures.tables(j))).isEqualTo(before);assertThat(j.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='15' AND success=TRUE",Long.class)).isEqualTo(1);}
    @Test void actualLowAndHighUniqueDeviceDriverIdentityMapsOnlyTheNamedConstraint(){for(String ordering:List.of("LOW","HIGH")){var j=db(null,ordering).jdbc();fixtures.tenant(j);devices(j);String a=fixtures.card(j,"a","One"),b=fixtures.card(j,"a","Two");current(j,a,"a","a-legacy-device-0",1);assertThatThrownBy(()->current(j,b,"a","a-legacy-device-0",1)).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimBindingConflicts.occupied(e)).isTrue());assertThatThrownBy(()->current(j,a,"a","a-legacy-device-1",1)).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimBindingConflicts.occupied(e)).isFalse());assertThatThrownBy(()->current(j,b,"a","b-legacy-device-0",1)).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimBindingConflicts.occupied(e)).isFalse());j.execute("ALTER TABLE sim_card_associations DROP CONSTRAINT uq_sim_card_associations_tenant_device");j.execute("ALTER TABLE sim_card_associations ADD CONSTRAINT uq_sim_card_associations_tenant_device_lookalike UNIQUE(tenant_id,device_id)");assertThatThrownBy(()->current(j,b,"a","a-legacy-device-0",1)).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimBindingConflicts.occupied(e)).isFalse());j.execute("ALTER TABLE sim_card_associations DROP CONSTRAINT uq_sim_card_associations_tenant_device_lookalike");j.execute("ALTER TABLE sim_card_associations ADD CONSTRAINT uq_sim_card_associations_tenant_device UNIQUE(tenant_id,revision)");assertThatThrownBy(()->current(j,b,"a","a-legacy-device-1",1)).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimBindingConflicts.occupied(e)).isFalse());}}
    @Test void multiplePersistedEmptyStatesAreAllowedButVirtualZeroIsNotInserted(){for(String ordering:List.of("LOW","HIGH")){var j=db(null,ordering).jdbc();fixtures.tenant(j);for(String name:List.of("One","Two","Three"))current(j,fixtures.card(j,"a",name),"a",null,2);assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_card_associations WHERE device_id IS NULL",Long.class)).isEqualTo(3);String card=fixtures.card(j,"a","Virtual");assertThatThrownBy(()->current(j,card,"a",null,0)).isInstanceOf(DataAccessException.class);}}
    @Test void compositeForeignKeysProtectCurrentCardDeviceAndBothHistoryDirections(){var j=db(null,"LOW").jdbc();fixtures.tenant(j);devices(j);fixtures.user(j,"actor","PLATFORM",false);String a=fixtures.card(j,"a","One");assertThatThrownBy(()->current(j,a,"b","b-legacy-device-0",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->current(j,UUID.randomUUID().toString(),"a","a-legacy-device-0",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,a,"a",1,"BIND",null,"b-legacy-device-0")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,a,"a",1,"UNBIND","b-legacy-device-0",null)).isInstanceOf(DataAccessException.class);change(j,a,"a",1,"BIND",null,"a-legacy-device-0");change(j,a,"a",2,"UNBIND","a-legacy-device-0",null);assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_card_association_changes",Long.class)).isEqualTo(2);}
    @Test void historyDirectionPositiveSafeRevisionUuidAndUniqueRevisionAreDatabaseEnforced(){var j=db(null,"LOW").jdbc();fixtures.tenant(j);devices(j);fixtures.user(j,"actor","PLATFORM",false);String card=fixtures.card(j,"a","One");for(String operation:List.of("CREATE","EDIT","OTHER"))assertThatThrownBy(()->change(j,card,"a",1,operation,null,"a-legacy-device-0")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",0,"BIND",null,"a-legacy-device-0")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",SimBindingInputsMaximum(),"BIND",null,"a-legacy-device-0")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",1,"BIND","a-legacy-device-0","a-legacy-device-1")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",1,"UNBIND",null,null)).isInstanceOf(DataAccessException.class);change(j,card,"a",1,"BIND",null,"a-legacy-device-0");assertThatThrownBy(()->change(j,card,"a",1,"BIND",null,"a-legacy-device-0")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->j.update("UPDATE sim_card_association_changes SET id='NOT-UUID'")).isInstanceOf(DataAccessException.class);}
    private long SimBindingInputsMaximum(){return 9_007_199_254_740_992L;}
}
